{"refs":["lines","shipping","tax_percent"],"code":"from fractions import Fraction

def _round_half_up(x):
    return (2 * x.numerator + x.denominator) // (2 * x.denominator)

def solve(facts):
    subtotal = 0
    for line in facts['lines']:
        discount = Fraction(line['discount_percent'])
        amount = Fraction(line['qty'] * line['unit_cents']) * (1 - discount / 100)
        subtotal += _round_half_up(amount)
    tax = _round_half_up(Fraction(subtotal) * Fraction(facts['tax_percent']) / 100)
    return {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}

def check(answer, facts):
    subtotal = 0
    for line in facts['lines']:
        # Compute discounted amount as an exact rational, then use quotient/remainder rounding.
        d = Fraction(line['discount_percent'])
        n = line['qty'] * line['unit_cents'] * (100 * d.denominator - d.numerator)
        den = 100 * d.denominator
        q, r = divmod(n, den)
        subtotal += q + (2 * r >= den)
    t = Fraction(facts['tax_percent'])
    n = subtotal * t.numerator
    den = 100 * t.denominator
    q, r = divmod(n, den)
    tax = q + (2 * r >= den)
    return isinstance(answer, dict) and answer == {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}"}
